65	export async function loader({ params, request }: Route.LoaderArgs) {
66	  const slug = params.slug;
67	  const course = getCourseBySlug(slug);
68	
69	  if (!course) {
70	    throw data("Course not found", { status: 404 });
71	  }
72	
73	  const courseWithDetails = getCourseWithDetails(course.id);
74	  if (!courseWithDetails) {
75	    throw data("Course not found", { status: 404 });
76	  }
77	
78	  const lessonCount = getLessonCountForCourse(course.id);
79	  const currentUserId = await getCurrentUserId(request);
80	
81	  let enrolled = false;
82	  let progress = 0;
83	  let lessonProgressMap: Record<number, string> = {};
84	  let nextLessonId: number | null = null;
85	
86	  if (currentUserId) {
87	    enrolled = isUserEnrolled(currentUserId, course.id);
88	
89	    if (enrolled) {
90	      progress = calculateProgress(currentUserId, course.id, false, false);
91	
92	      const progressRecords = getLessonProgressForCourse(
93	        currentUserId,
94	        course.id
95	      );
96	      for (const record of progressRecords) {
97	        lessonProgressMap[record.lessonId] = record.status;
98	      }
99	
100	      const nextLesson = getNextIncompleteLesson(currentUserId, course.id);
101	      nextLessonId = nextLesson?.id ?? null;
102	    }
103	  }
104	
105	  // Render sales copy from Markdown to HTML server-side
106	  const salesCopyHtml = courseWithDetails.salesCopy
107	    ? await renderMarkdown(courseWithDetails.salesCopy)
108	    : null;
109	
110	  const country = await resolveCountry(request);
111	  const pppPrice = courseWithDetails.pppEnabled
112	    ? calculatePppPrice(courseWithDetails.price, country)
113	    : courseWithDetails.price;
114	  const tierInfo = getCountryTierInfo(country);
115	
116	  const reviews = getReviewsForCourse(course.id);
117	  const averageRating = getAverageRatingForCourse(course.id);
118	  const reviewCount = getReviewCountForCourse(course.id);
119	  const userReview = currentUserId
120	    ? getUserReviewForCourse(currentUserId, course.id)
121	    : null;
122	
123	  return {
124	    course: courseWithDetails,
125	    salesCopyHtml,
126	    lessonCount,
127	    enrolled,
128	    progress,
129	    lessonProgressMap,
130	    nextLessonId,
131	    currentUserId,
132	    pppPrice,
133	    tierInfo,
134	    reviews,
135	    averageRating,
136	    reviewCount,
137	    userReview: userReview ?? null,
138	  };
139	}
140	
141	export async function action({ params, request }: Route.ActionArgs) {
142	  const currentUserId = await getCurrentUserId(request);
143	  if (!currentUserId) {
144	    throw data("Sign in required", { status: 401 });
145	  }
146	
147	  const course = getCourseBySlug(params.slug);
148	  if (!course) {
149	    throw data("Course not found", { status: 404 });
150	  }
151	
152	  if (!isUserEnrolled(currentUserId, course.id)) {
153	    throw data("You must be enrolled to leave a review", { status: 403 });
154	  }
155	
156	  const formData = await request.formData();
157	  const intent = formData.get("intent");
158	
159	  if (intent === "submit_review") {
160	    const rating = Number(formData.get("rating"));
161	    const body = (formData.get("body") as string).trim() || null;
162	
163	    if (!rating || rating < 1 || rating > 5) {
164	      return { error: "Please select a rating between 1 and 5." };
165	    }
166	
167	    createOrUpdateReview(currentUserId, course.id, rating, body);
168	    return { success: true };
169	  }
170	
171	  if (intent === "delete_review") {
172	    const reviewId = Number(formData.get("reviewId"));
173	    deleteReview(reviewId, currentUserId);
174	    return { success: true };
175	  }
176	
177	  return null;
178	}
