537	function CourseContent({
538	  course,
539	  enrolled,
540	  isInstructor,
541	  lessonProgressMap,
542	}: {
543	  course: {
544	    id: number;
545	    slug: string;
546	    modules: Array<{
547	      id: number;
548	      title: string;
549	      lessons: Array<{
550	        id: number;
551	        title: string;
552	        durationMinutes: number | null;
553	      }>;
554	    }>;
555	  };
556	  enrolled: boolean;
557	  isInstructor: boolean;
558	  lessonProgressMap: Record<number, string>;
559	}) {
560	  return (
561	    <div>
562	      <h2 className="mb-4 text-2xl font-bold">Course Content</h2>
563	      {course.modules.length === 0 ? (
564	        <p className="text-muted-foreground">
565	          No content has been added to this course yet.
566	        </p>
567	      ) : (
568	        <div className="space-y-4">
569	          {course.modules.map((mod) => (
570	            <Card key={mod.id}>
571	              <CardHeader>
572	                <h3 className="font-semibold">
573	                  <Link
574	                    to={`/courses/${course.slug}/${mod.id}`}
575	                    className="hover:underline"
576	                  >
577	                    {mod.title}
578	                  </Link>
579	                </h3>
580	                <p className="text-sm text-muted-foreground">
581	                  {mod.lessons.length} lessons
582	                </p>
583	              </CardHeader>
584	              <CardContent>
585	                <ul className="space-y-2">
586	                  {mod.lessons.map((lesson) => {
587	                    const status = lessonProgressMap[lesson.id];
588	                    const isCompleted =
589	                      status === LessonProgressStatus.Completed;
590	                    const isLessonInProgress =
591	                      status === LessonProgressStatus.InProgress;
592	
593	                    if (isInstructor) {
594	                      return (
595	                        <li key={lesson.id}>
596	                          <Link
597	                            to={`/instructor/${course.id}/lessons/${lesson.id}`}
598	                            className="flex items-center gap-3 rounded-md px-3 py-2 text-sm hover:bg-muted"
599	                          >
600	                            <Pencil className="size-4 shrink-0 text-muted-foreground" />
601	                            <span className="flex-1">{lesson.title}</span>
602	                            {lesson.durationMinutes && (
603	                              <span className="flex items-center gap-1 text-xs text-muted-foreground">
604	                                <Clock className="size-3" />
605	                                {formatDuration(
606	                                  lesson.durationMinutes,
607	                                  true,
608	                                  false,
609	                                  false
610	                                )}
611	                              </span>
612	                            )}
613	                          </Link>
614	                        </li>
615	                      );
616	                    }
617	
618	                    return (
619	                      <li key={lesson.id}>
620	                        {enrolled ? (
621	                          <Link
622	                            to={`/courses/${course.slug}/lessons/${lesson.id}`}
623	                            className="flex items-center gap-3 rounded-md px-3 py-2 text-sm hover:bg-muted"
624	                          >
625	                            {isCompleted ? (
626	                              <CheckCircle2 className="size-4 shrink-0 text-green-500" />
