628	                              <PlayCircle className="size-4 shrink-0 text-blue-500" />
629	                            ) : (
630	                              <Circle className="size-4 shrink-0 text-muted-foreground" />
631	                            )}
632	                            <span className="flex-1">{lesson.title}</span>
633	                            {lesson.durationMinutes && (
634	                              <span className="flex items-center gap-1 text-xs text-muted-foreground">
635	                                <Clock className="size-3" />
636	                                {formatDuration(
637	                                  lesson.durationMinutes,
638	                                  true,
639	                                  false,
640	                                  false
641	                                )}
642	                              </span>
643	                            )}
644	                          </Link>
645	                        ) : (
646	                          <div className="flex items-center gap-3 px-3 py-2 text-sm">
647	                            <Circle className="size-4 shrink-0 text-muted-foreground" />
648	                            <span className="flex-1">{lesson.title}</span>
649	                            {lesson.durationMinutes && (
650	                              <span className="flex items-center gap-1 text-xs text-muted-foreground">
651	                                <Clock className="size-3" />
652	                                {formatDuration(
653	                                  lesson.durationMinutes,
654	                                  true,
655	                                  false,
656	                                  false
657	                                )}
658	                              </span>
659	                            )}
660	                          </div>
661	                        )}
662	                      </li>
