export function meta({ data: loaderData }: Route.MetaArgs) {
  const title = loaderData?.course?.title ?? "Course";
  return [
    { title: `${title} — Cadence` },
    { name: "description", content: loaderData?.course?.description ?? "" },
  ];
}

export async function loader({ params, request }: Route.LoaderArgs) {
  const slug = params.slug;
  const course = getCourseBySlug(slug);

  if (!course) {
    throw data("Course not found", { status: 404 });
  }

  const courseWithDetails = getCourseWithDetails(course.id);
  if (!courseWithDetails) {
    throw data("Course not found", { status: 404 });
  }

  const lessonCount = getLessonCountForCourse(course.id);
  const currentUserId = await getCurrentUserId(request);

  let enrolled = false;
  let progress = 0;
  let lessonProgressMap: Record<number, string> = {};
  let nextLessonId: number | null = null;

  if (currentUserId) {
    enrolled = isUserEnrolled(currentUserId, course.id);

    if (enrolled) {
      progress = calculateProgress(currentUserId, course.id, false, false);

      const progressRecords = getLessonProgressForCourse(
        currentUserId,
        course.id
      );
      for (const record of progressRecords) {
        lessonProgressMap[record.lessonId] = record.status;
      }

      const nextLesson = getNextIncompleteLesson(currentUserId, course.id);
      nextLessonId = nextLesson?.id ?? null;
    }
  }

  // Render sales copy from Markdown to HTML server-side
  const salesCopyHtml = courseWithDetails.salesCopy
    ? await renderMarkdown(courseWithDetails.salesCopy)
    : null;

  const country = await resolveCountry(request);
  const pppPrice = courseWithDetails.pppEnabled
    ? calculatePppPrice(courseWithDetails.price, country)
    : courseWithDetails.price;
  const tierInfo = getCountryTierInfo(country);

  const reviews = getReviewsForCourse(course.id);
  const averageRating = getAverageRatingForCourse(course.id);
  const reviewCount = getReviewCountForCourse(course.id);
  const userReview = currentUserId
    ? getUserReviewForCourse(currentUserId, course.id)
    : null;

  return {
    course: courseWithDetails,
    salesCopyHtml,
    lessonCount,
    enrolled,
    progress,
    lessonProgressMap,
    nextLessonId,
    currentUserId,
    pppPrice,
    tierInfo,
    reviews,
    averageRating,
    reviewCount,
    userReview: userReview ?? null,
  };
}

export async function action({ params, request }: Route.ActionArgs) {
  const currentUserId = await getCurrentUserId(request);
  if (!currentUserId) {
    throw data("Sign in required", { status: 401 });
  }

  const course = getCourseBySlug(params.slug);
  if (!course) {
    throw data("Course not found", { status: 404 });
  }

  if (!isUserEnrolled(currentUserId, course.id)) {
    throw data("You must be enrolled to leave a review", { status: 403 });
  }

  const formData = await request.formData();
  const intent = formData.get("intent");

  if (intent === "submit_review") {
    const rating = Number(formData.get("rating"));
    const body = (formData.get("body") as string).trim() || null;

    if (!rating || rating < 1 || rating > 5) {
      return { error: "Please select a rating between 1 and 5." };
    }

    createOrUpdateReview(currentUserId, course.id, rating, body);
    return { success: true };
  }

  if (intent === "delete_review") {
    const reviewId = Number(formData.get("reviewId"));
    deleteReview(reviewId, currentUserId);
    return { success: true };
  }

  return null;
}

